/**
 * Modality viewer component exports.
 */
export * from './email';
export * from './sms';

/**
 * Generic modality detail page with modality-specific viewers.
 */
import { useParams } from 'react-router-dom';
import { 
  Mail, 
  MessageSquare, 
  Calendar, 
  MessageCircle, 
  MapPin, 
  Cloud, 
  Clock 
} from 'lucide-react';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { ScrollArea } from '@/components/ui/scroll-area';
import { useModalityState } from '@/api';
import { EmailViewer } from '@/components/modalities/email';
import { SMSViewer } from '@/components/modalities/sms';

const modalityIcons: Record<string, React.ComponentType<{ className?: string }>> = {
  email: Mail,
  sms: MessageSquare,
  chat: MessageCircle,
  calendar: Calendar,
  location: MapPin,
  weather: Cloud,
  time: Clock,
};

/**
 * Render modality-specific viewer component.
 */
function ModalityViewerContent({ modality }: { modality: string }) {
  // Email has a custom viewer
  if (modality === 'email') {
    return <EmailViewer />;
  }

  // SMS has a custom viewer
  if (modality === 'sms') {
    return <SMSViewer />;
  }

  // Other modalities use generic JSON viewer (to be replaced)
  return <GenericModalityViewer modality={modality} />;
}

import type { 
  SMSState, 
  SMSMessage,
  ConversationFilter,
  ConversationDisplayItem 
} from './types';

import { 
  MessageSquare, 
  Users, 
  Pin, 
  BellOff, 
  Archive
} from 'lucide-react';

import {
  MessageSquarePlus,
  Trash2,
  Archive,
  Pin,
  PinOff,
  BellOff,
  Bell,
  RefreshCw,
  ArchiveRestore,
} from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Separator } from '@/components/ui/separator';

