 * Type definitions for the SMS Viewer component.
 * These match the backend SMS state models with UI-specific extensions.
 * 
 * NOTE: Contact name resolution is a placeholder pending Contacts modality.
 * When Contacts is implemented, integrate lookups for display names.
 */

/**
 * Attachment on an SMS/RCS message.
 */
export interface MessageAttachment {
  filename: string;
  size: number;
  mime_type: string;
  attachment_id: string;
  thumbnail_url?: string;
  duration?: number;
}

/**
 * Emoji reaction on a message.
 */
export interface MessageReaction {
  reaction_id: string;
  message_id: string;
  phone_number: string;
  emoji: string;
  timestamp: string;
}

/**
 * Participant in a group conversation.
 */
export interface GroupParticipant {
  phone_number: string;
  is_admin: boolean;
  joined_at: string;
  left_at?: string;
}

/**
 * SMS/RCS message as stored in the backend.
 */
export interface SMSMessage {
  message_id: string;
  thread_id: string;
  from_number: string;
  to_numbers: string[];
  body: string;
  attachments: MessageAttachment[];
  reactions: MessageReaction[];
  message_type: 'sms' | 'rcs';
  direction: 'incoming' | 'outgoing';
  sent_at: string;
  delivered_at?: string;
  read_at?: string;
  is_read: boolean;
  delivery_status: 'sending' | 'sent' | 'delivered' | 'failed' | 'read';
  edited_at?: string;
  is_deleted: boolean;
  replied_to_message_id?: string;
  is_spam: boolean;
}

/**
 * Conversation thread containing messages.
 */
export interface SMSConversation {
  thread_id: string;
  conversation_type: 'one_on_one' | 'group';
  participants: GroupParticipant[];
  group_name?: string;
  group_photo_url?: string;
  created_at: string;
  created_by?: string;
  last_message_at: string;
  message_count: number;
  unread_count: number;
  is_pinned: boolean;
  is_muted: boolean;
  is_archived: boolean;
  draft_message?: string;
}

/**
 * Complete SMS state from the backend.
 */
export interface SMSState {
  modality_type: 'sms';
  current_time: string;
  user_phone_number: string;
  messages: Record<string, SMSMessage>;
  conversations: Record<string, SMSConversation>;
  total_message_count: number;
  unread_count: number;
  total_conversation_count: number;
}

/**
 * Filter options for conversation list.
 */
export type ConversationFilter = 'all' | 'unread' | 'groups' | 'archived';

/**
 * Compose message form data.
 */
export interface ComposeMessageData {
  to_numbers: string[];
  body: string;
  message_type: 'sms' | 'rcs';
  attachments: MessageAttachment[];
  replied_to_message_id?: string;
}

/**
 * Display item for conversation list.
 * Extends conversation data with computed display properties.
 */
export interface ConversationDisplayItem {
  conversation: SMSConversation;
  lastMessage?: SMSMessage;
  displayName: string;
  displayNumber: string;
  lastMessagePreview: string;
  lastMessageTime: string;
  isGroup: boolean;
  participantCount: number;
}

/**
 * Contact info placeholder.
 * TODO: Replace with actual Contact type when Contacts modality is implemented.
 */
export interface ContactInfo {
  phone_number: string;
  display_name?: string;
  // Future fields from Contacts modality:
  // avatar_url?: string;
  // is_blocked?: boolean;
}

/**
 * Resolve a phone number to a display name.
 * Placeholder for Contacts modality integration.
 * 
 * @param phoneNumber - The phone number to resolve
 * @param contacts - Map of phone numbers to contact info (placeholder)
 * @returns Display name if found, otherwise formatted phone number
 */
export function resolveContactName(
  phoneNumber: string,
  contacts?: Map<string, ContactInfo>
): string {
  // TODO: When Contacts modality is available, use it to look up names
  const contact = contacts?.get(phoneNumber);
  if (contact?.display_name) {
    return contact.display_name;
  }
  // Return the phone number as-is for now
  return phoneNumber;
}

/**
 * Format a phone number for display.
 * Placeholder for more sophisticated formatting.
 */
export function formatPhoneNumber(phoneNumber: string): string {
  // Basic US phone number formatting
  const cleaned = phoneNumber.replace(/\D/g, '');
  if (cleaned.length === 10) {
    return `(${cleaned.slice(0, 3)}) ${cleaned.slice(3, 6)}-${cleaned.slice(6)}`;
  }
  if (cleaned.length === 11 && cleaned.startsWith('1')) {
    return `+1 (${cleaned.slice(1, 4)}) ${cleaned.slice(4, 7)}-${cleaned.slice(7)}`;
  }
  // Return as-is if we can't parse it
  return phoneNumber;
}

/**
 * SMS action types for API operations.
 */
export type SMSAction =
  | 'send'
  | 'receive'
  | 'delete'
  | 'mark_read'
  | 'mark_unread'
  | 'react'
  | 'archive'
  | 'unarchive'
  | 'pin'
  | 'unpin'
  | 'mute'
  | 'unmute';
"}

{"content": "/**
 * Conversation list component for SMS viewer.
 * Displays all conversations with filters and selection.
 */
import { useMemo } from 'react';
import { formatDistanceToNow, parseISO } from 'date-fns';
import { 
  MessageSquare, 
  Users, 
  Pin, 
  BellOff, 
  Archive,
  Circle
} from 'lucide-react';
import { cn } from '@/lib/utils';
import { ScrollArea } from '@/components/ui/scroll-area';
import { Badge } from '@/components/ui/badge';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';
import type { 
  SMSState, 
  SMSConversation, 
  SMSMessage,
  ConversationFilter,
  ConversationDisplayItem 
} from './types';
import { resolveContactName } from './types';

interface ConversationListProps {
  smsState: SMSState | null;
  selectedThreadId: string | null;
  filter: ConversationFilter;
  onFilterChange: (filter: ConversationFilter) => void;
  onConversationSelect: (threadId: string) => void;
}

/**
 * Build display items for conversations with computed properties.
 */
function buildConversationDisplayItems(
  smsState: SMSState
): ConversationDisplayItem[] {
  const items: ConversationDisplayItem[] = [];

  for (const conversation of Object.values(smsState.conversations)) {
    // Get messages for this conversation
    const conversationMessages = Object.values(smsState.messages)
      .filter(msg => msg.thread_id === conversation.thread_id && !msg.is_deleted)
      .sort((a, b) => new Date(b.sent_at).getTime() - new Date(a.sent_at).getTime());

    const lastMessage = conversationMessages[0];

    // Build display name
    let displayName: string;
    let displayNumber: string;

    if (conversation.conversation_type === 'group') {
      displayName = conversation.group_name || 'Group Chat';
      displayNumber = `${conversation.participants.filter(p => !p.left_at).length} participants`;
    } else {
      // One-on-one: find the other participant (not the user)
      const otherParticipant = conversation.participants.find(
        p => p.phone_number !== smsState.user_phone_number && !p.left_at
      );
      displayNumber = otherParticipant?.phone_number || 'Unknown';
      // TODO: Integrate with Contacts modality for name lookup
      displayName = resolveContactName(displayNumber);
    }

    // Build message preview
    let lastMessagePreview = '';
    if (lastMessage) {
      const prefix = lastMessage.direction === 'outgoing' ? 'You: ' : '';
      lastMessagePreview = prefix + (lastMessage.body.length > 40 
        ? lastMessage.body.slice(0, 40) + '...' 
        : lastMessage.body);
    }

    // Format time
    let lastMessageTime = '';
    if (lastMessage) {
      try {
        lastMessageTime = formatDistanceToNow(parseISO(lastMessage.sent_at), { 
          addSuffix: false 
        });
      } catch {
        lastMessageTime = '';
      }
    }

    items.push({
      conversation,
      lastMessage,
      displayName,
      displayNumber,
      lastMessagePreview,
      lastMessageTime,
      isGroup: conversation.conversation_type === 'group',
      participantCount: conversation.participants.filter(p => !p.left_at).length,
    });
  }

  // Sort: pinned first, then by last message time
  return items.sort((a, b) => {
    if (a.conversation.is_pinned && !b.conversation.is_pinned) return -1;
    if (!a.conversation.is_pinned && b.conversation.is_pinned) return 1;

    const aTime = a.lastMessage?.sent_at || a.conversation.created_at;
    const bTime = b.lastMessage?.sent_at || b.conversation.created_at;
    return new Date(bTime).getTime() - new Date(aTime).getTime();
  });
}

/**
 * Filter conversations based on selected filter.
 */
function filterConversations(
  items: ConversationDisplayItem[],
  filter: ConversationFilter
): ConversationDisplayItem[] {
  switch (filter) {
    case 'unread':
      return items.filter(item => 
        item.conversation.unread_count > 0 && !item.conversation.is_archived
      );
    case 'groups':
      return items.filter(item => 
        item.isGroup && !item.conversation.is_archived
      );
    case 'archived':
      return items.filter(item => item.conversation.is_archived);
    case 'all':
    default:
      return items.filter(item => !item.conversation.is_archived);
  }
}

/**
 * Get delivery status indicator for outgoing messages.
 */
function DeliveryStatusIndicator({ message }: { message?: SMSMessage }) {
  if (!message || message.direction !== 'outgoing') return null;

  switch (message.delivery_status) {
    case 'read':
      return <span className="text-blue-500 text-xs">✓✓</span>;
    case 'delivered':
      return <span className="text-muted-foreground text-xs">✓✓</span>;
    case 'sent':
      return <span className="text-muted-foreground text-xs">✓</span>;
    case 'sending':
      return <span className="text-muted-foreground text-xs">○</span>;
    case 'failed':
      return <span className="text-destructive text-xs">!</span>;
    default:
      return null;
  }
}

/**
 * Single conversation list item.
 */
function ConversationItem({
  item,
  isSelected,
  onClick,
}: {
  item: ConversationDisplayItem;
  isSelected: boolean;
  onClick: () => void;
}) {
  const { conversation, lastMessage } = item;

  return (
    <button
      onClick={onClick}
      className={cn(
        'w-full text-left p-3 border-b transition-colors',
        'hover:bg-muted/50',
        isSelected && 'bg-muted',
        conversation.is_muted && 'opacity-60'
      )}
    >
      <div className="flex items-start gap-2">
        {/* Icon */}
        <div className="flex-shrink-0 mt-0.5">
          {item.isGroup ? (
            <Users className="h-5 w-5 text-muted-foreground" />
          ) : (
            <MessageSquare className="h-5 w-5 text-muted-foreground" />
          )}
        </div>

        {/* Content */}
        <div className="flex-1 min-w-0">
          {/* Header row */}
          <div className="flex items-center gap-1">
            {conversation.is_pinned && (
              <Pin className="h-3 w-3 text-muted-foreground flex-shrink-0" />
            )}
            {conversation.is_muted && (
              <BellOff className="h-3 w-3 text-muted-foreground flex-shrink-0" />
            )}
            {conversation.is_archived && (
              <Archive className="h-3 w-3 text-muted-foreground flex-shrink-0" />
            )}
            <span className={cn(
              'font-medium truncate',
              conversation.unread_count > 0 && 'font-semibold'
            )}>
              {item.displayName}
            </span>
          </div>

          {/* Phone number or participant count */}
          <div className="text-xs text-muted-foreground truncate">
            {item.displayNumber}
          </div>

          {/* Last message preview */}
          {item.lastMessagePreview && (
            <div className="flex items-center gap-1 mt-0.5">
              <span className={cn(
                'text-sm truncate',
                conversation.unread_count > 0 
                  ? 'text-foreground' 
                  : 'text-muted-foreground'
              )}>
                {item.lastMessagePreview}
              </span>
            </div>
          )}
        </div>

        {/* Right side - time and unread */}
        <div className="flex-shrink-0 text-right">
          {item.lastMessageTime && (
            <div className="text-xs text-muted-foreground">
              {item.lastMessageTime}
            </div>
          )}
          <div className="flex items-center gap-1 justify-end mt-1">
            <DeliveryStatusIndicator message={lastMessage} />
            {conversation.unread_count > 0 && (
              <Badge 
                variant="default" 
                className="h-5 min-w-[20px] px-1.5 text-xs"
              >
                {conversation.unread_count}
              </Badge>
            )}
          </div>
        </div>
      </div>
    </button>
  );
}

export function ConversationList({
  smsState,
  selectedThreadId,
  filter,
  onFilterChange,
  onConversationSelect,
}: ConversationListProps) {
  // Build and filter conversation items
  const filteredItems = useMemo(() => {
    if (!smsState) return [];
    const allItems = buildConversationDisplayItems(smsState);
    return filterConversations(allItems, filter);
  }, [smsState, filter]);

  // Count unread for filter badge
  const unreadCount = useMemo(() => {
    if (!smsState) return 0;
    return Object.values(smsState.conversations)
      .filter(c => !c.is_archived)
      .reduce((sum, c) => sum + c.unread_count, 0);
  }, [smsState]);

  if (!smsState) {
    return (
      <div className="w-72 border-r bg-background flex items-center justify-center">
        <span className="text-muted-foreground">Loading...</span>
      </div>
    );
  }

  return (
    <div className="w-72 border-r bg-background flex flex-col">
      {/* Filter selector */}
      <div className="p-2 border-b">
        <Select value={filter} onValueChange={(v) => onFilterChange(v as ConversationFilter)}>
          <SelectTrigger className="w-full">
            <SelectValue placeholder="Filter conversations" />
          </SelectTrigger>
          <SelectContent>
            <SelectItem value="all">All Conversations</SelectItem>
            <SelectItem value="unread">
              Unread Only {unreadCount > 0 && `(${unreadCount})`}
            </SelectItem>
            <SelectItem value="groups">Groups Only</SelectItem>
            <SelectItem value="archived">Archived</SelectItem>
          </SelectContent>
        </Select>
      </div>

      {/* Conversation list */}
      <ScrollArea className="flex-1">
        {filteredItems.length === 0 ? (
          <div className="p-4 text-center text-muted-foreground text-sm">
            {filter === 'all' && 'No conversations yet'}
            {filter === 'unread' && 'No unread messages'}
            {filter === 'groups' && 'No group conversations'}
            {filter === 'archived' && 'No archived conversations'}
          </div>
        ) : (
          filteredItems.map((item) => (
            <ConversationItem
              key={item.conversation.thread_id}
              item={item}
              isSelected={item.conversation.thread_id === selectedThreadId}
              onClick={() => onConversationSelect(item.conversation.thread_id)}
            />
          ))
        )}
      </ScrollArea>
    </div>
  );
}
